import React from "react";

const HeroSection = () => {
  return (
    <section className="relative bg-cover bg-center h-screen transition-all duration-500">
      <div className="min-w-full max-h-full md:w-auto md:h-auto">
      <video
        className="absolute top-0 left-0  object-cover"
        autoPlay
        loop
        muted
      >
        <source src="./videos/Doad_video.mp4" type="video/mp4" />
        Your browser does not support the video tag.
      </video>
      </div>
    </section>
  );
};

export default HeroSection;
